CREATE TABLE t1(a INTEGER PRIMARY KEY, b INT); CREATE TABLE t2(c INTEGER PRIMARY KEY, d INT); CREATE TABLE t3(e INTEGER PRIMARY KEY, f INT); CREATE TABLE t4(g INTEGER PRIMARY KEY, h INT);
EXPLAIN QUERY PLAN SELECT * FROM t1, t2 CROSS JOIN t3, t4 WHERE t4.g=1 AND t1.a=t4.h AND t2.c=t1.b AND t3.e=t2.d;
EXPLAIN QUERY PLAN SELECT * FROM t1, t2 CROSS JOIN t3, t4 WHERE t2.c=1 AND t3.e=t2.d AND t4.g=t3.f AND t1.a=t4.h;
DROP TABLE IF EXISTS t1; CREATE TABLE t1(a TEXT); INSERT INTO t1 VALUES('A'),('b'); SELECT * FROM t1 WHERE (a='a' COLLATE nocase) OR a='b' ORDER BY +a;
CREATE INDEX t1_a ON t1(a); SELECT * FROM t1 WHERE (a='a' COLLATE nocase) OR a='b' ORDER BY +a;
